INSERT INTO "record_versions" ("id","model_api_key","record_id","version_number","snapshot","created_at","action","actor_type","actor_label","actor_token_id") VALUES('y4ugjaooeu','editorial','uyjk9adkii',1,'{"title":"Why We Love Skreið","slug":"why-we-love-skreid","excerpt":"A Basque-inspired tapas bar in a charming black house on Laugavegur. Great wine, great vibes, and one of our favorite spots in Reykjavík.","date":"2025-02-17T00:00:00.000Z","image":"p66iptw5yn","content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Skreið is a Basque-inspired tapas restaurant and bar tucked into a charming black house at Laugavegur 4. It was opened a couple of years ago by friends Steinþór and Davíð Örn, and the inspiration comes straight from their travels through the Basque Country."}]},{"type":"paragraph","children":[{"type":"span","value":"The vibe is laid-back but polished — cool staff, good music, the kind of place that works equally well for a casual drink or a proper date night. The interior has that effortless Scandinavian-meets-Southern-European feel that just makes you want to stay longer than you planned."}]},{"type":"heading","level":2,"children":[{"type":"span","value":"The wine"}]},{"type":"paragraph","children":[{"type":"span","value":"For a small place, Skreið has an impressively deep wine list. The focus is on Spanish wines, which makes sense given the Basque influence, but they also keep things interesting with bottles from other regions. The staff actually knows the list and can guide you to something great based on what you’re eating."}]},{"type":"block","item":"9xvd2p5nwe"},{"type":"block","item":"32bei45v3n"},{"type":"heading","level":2,"children":[{"type":"span","value":"The food"}]},{"type":"paragraph","children":[{"type":"span","value":"Think tapas with Icelandic ingredients. Small plates made for sharing, bold flavours, and everything comes out looking beautiful. It’s the kind of menu where you order too much and don’t regret it."}]},{"type":"paragraph","children":[{"type":"span","value":"We recommend Skreið for anyone who loves tapas and good vibes.","marks":["strong"]},{"type":"span","value":" It’s in our "},{"type":"span","value":"Reykjavík Food Guide","marks":["strong"]},{"type":"span","value":" for a reason — this is a perfect date night spot."}]}]}},"blocks":{"32bei45v3n":{"_type":"image_block","image":"udl7z0hejy","caption":"Wine bottle candle at Skreið"},"9xvd2p5nwe":{"_type":"image_block","image":"p66iptw5yn","caption":"Skreið restaurant sign"}}}}','2026-03-23T19:55:29.459Z','publish','editor','Sunna','etid_e8b998aa-9d36-4617-a2dc-13f1d4280c67');
