rch/Le+Kock+Tryggvagata+Reykjavik","website":"lekock.is","phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"6dqrmfpjd5":{"_type":"venue","name":"Kaffi Lækur","address":"Laugarnesvegur 75","description":"A neighbourhood gem popular with new parents. Dedicated kids’ corner with toys and books. Sourdough flatbakes are hearty and delicious. Slightly off the tourist path.","note":"Kids’ corner with toys and books.","time":null,"is_free":0,"location":{"latitude":64.1422,"longitude":-21.9058},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Kaffi+Lækur+Laugarnesvegur+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"2mfpcb8wu4":{"_type":"venue","name":"Chickpea","address":"Hallveigarstígur 1","description":"Family-run vegetarian spot with the best falafel in town. Generous portions, freshly made, warm and unhurried vibe. Great for kids who like wraps and hummus.","note":"Vegetarian/vegan. Casual and quick.","time":null,"is_free":0,"location":{"latitude":64.1457,"longitude":-21.9341},"opening_hours":"Mo-Su 10:00-20:00","google_maps_url":"https://www.google.com/maps/search/Chickpea+Reykjavik","website":"chickpea.is","phone":null,"best_of_award":null,"grapevine_url":null,"image":"e59v159sv3"}}}},"s3":{"_type":"section","title":"Dinner","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"4bpssf44nj"},{"type":"block","item":"r091s3bmwq"}]}},"blocks":{"4bpssf44nj":{"_type":"venue","name":"Búllan","address":"Höfði (Bolholt 6)","description":"The Höfði location is the one you want with kids. Walls covered in drawings done by children during meals — your kids can add to the collection. No-frills burgers, zero pretension.","note":"Höfði location best for families. Kids’ drawings on walls.","time":null,"is_free":0,"location":{"latitude":64.1355,"longitude":-21.9029},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Búllan+Höfði+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"r091s3bmwq":{"_type":"venue","name":"Jómfrúin","address":"Lækjargata 4","description":"Classic Danish smørrebrød — open-faced sandwiches perfect for kids who like to pick and choose toppings. Best service in town means they’ll be patient with your order taking twice as long.","note":"Best service in town. Patient with families.","time":null,"is_free":0,"location":{"latitude":64.1468,"longitude":-21.9374},"opening_hours":"Mo-Su 11:30-22:00","google_maps_url":"https://www.google.com/maps/search/Jómfrúin+Lækjargata+Reykjavik","website":null,"phone":"551 0100","best_of_award":null,"grapevine_url":null,"image":"qzs1eqbdl3"}}}},"s4":{"_type":"section","title":"Sweet Treats & Ice Cream","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"3gt0bkcr5j"}]}},"blocks":{"3gt0bkcr5j":{"_type":"venue","name":"DEIG Workshop","address":"Tryggvagata 14","description":"Doughnuts and bagels made fresh daily. The doughnuts are the obvious kid-magnet, but don’t sleep on the bagels. Perfect post-playground bribe.","note":"Right next to Le Kock — easy to combine visits.","time":null,"is_free":0,"location":{"latitude":64.1501,"longitude":-21.9434},"opening_hours":"Mo-Fr 07:00-17:00; Sa-Su 08:00-16:00","google_maps_url":"https://www.google.com/maps/search/DEIG+Workshop+Tryggvagata+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null}}}},"t1":{"_type":"text_block","heading":"Tips for Eating Out with Kids in Reykjavík","is_free":1,"content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Icelanders eat late.","marks":["strong"]},{"type":"span","value":" Dinner service starts at 17:00–18:00. If you go right when doors open, you’ll often have the place to yourself."}]},{"type":"paragraph","children":[{"type":"span","value":"Most places have highchairs.","marks":["strong"]},{"type":"span","value":" But they’re often the basic IKEA kind. If your child needs a specific setup, bring your own clip-on seat."}]},{"type":"paragraph","children":[{"type":"span","value":"Changing tables are rare.","marks":["strong"]},{"type":"span","value":" Outside of the bigger restaurants and shopping centres, you’ll mostly be improvising."}]},{"type":"paragraph","children":[{"type":"span","value":"Don’t stress about the kids.","marks":["strong"]},{"type":"span","value":" Reykjavík is extremely child-friendly as a culture. Nobody’s going to glare at you if your toddler is being a toddler."}]},{"type":"paragraph","children":[{"type":"span","value":"Book ahead for dinner.","marks":["strong"]},{"type":"span","value":" The best places are small. Mentioning you’re bringing kids when you book helps them seat you somewhere with more space."}]}]}},"blocks":{}}}}}}','2026-03-23T22:11:51.328Z','publish','editor','Sunna','etid_67388504-dc4b-4b53-aa82-48f6b1964253');
